  process.env.SCALEKIT_CLIENT_ID,
  process.env.SCALEKIT_CLIENT_SECRET
);

const REDIRECT_URI = 'http://localhost:3001/callback';

/**
 * GET /callback
 *
 * Handles the OAuth2 redirect from Scalekit after user authentication.
 * Exchanges the authorization code for tokens, decodes the ID token,
 * and returns the user's email and name as JSON.
 */
app.get('/callback', async (req, res) => {
  const { code, state } = req.query;

  if (!code) {
